<?php
declare(strict_types=1);
namespace Atlas\Platform\PatientResources\Domain;
final class PatientResourceVariant{/** @param array<string,string> $customizations */public function __construct(public readonly string $id,public readonly string $organizationId,public readonly string $resourceVersionId,public readonly array $customizations,public readonly string $createdAt,public readonly bool $replayed=false){}public function replayed():self{return new self($this->id,$this->organizationId,$this->resourceVersionId,$this->customizations,$this->createdAt,true);}public function toArray():array{return ['id'=>$this->id,'organization_id'=>$this->organizationId,'resource_version_id'=>$this->resourceVersionId,'customizations'=>$this->customizations,'created_at'=>$this->createdAt,'replayed'=>$this->replayed];}}
